// The isqrt example (examples/isqrt, #1966): a module that is a C function, its HDL generated by Silinx HLS and instanced
// by a VHDL top: the C test bench's C simulation and C/RTL co-simulation, in VHDL and in Verilog, its answers against an
// independent reference, the display's test bench on the HDL of both languages; no warnings anywhere. The flows common
// to every example: test/examples.test.js, test/ise/examples.test.js.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { compile, elaborate } from '../core/compile.js';
import { cToHdl } from '../core/c-hdl.js';
import { simulateC } from '../core/c-interp.js';
import { cosimulate } from '../core/c-cosim.js';
import { Simulator } from '../core/simulator.js';
import { viewHdl } from '../core/view-hdl.js';
import { example, runTestbench } from './examples-lib.mjs';

const ex = example('isqrt');
const FILE = 'src/isqrt.c';
const C = fs.readFileSync(path.join(ex.dir, FILE), 'utf8');

test('#1966 isqrt: the C is the module\'s base: no HDL file of it in the project, its HDL generated, its ports Vitis HLS\'s, no warnings', () => {
  assert.deepEqual(ex.project.files.map(f => f.path), ['src/sevenseg.vhd', 'src/isqrt_top.vhd', 'sim/tb_isqrt.vhd']);
  assert.deepEqual(fs.readdirSync(path.join(ex.dir, 'src')).sort(), ['isqrt.c', 'isqrt_top.vhd', 'sevenseg.vhd']);
  for (const lang of ['vhdl', 'verilog']) {
    const r = cToHdl(C, { file: FILE, lang });
    assert.deepEqual(r.diagnostics, []);
    assert.equal(r.sequential, true);
    assert.deepEqual(r.ports.map(p => [p.name, p.dir, p.w]), [['ap_clk', 'in', 1], ['ap_rst', 'in', 1], ['ap_start', 'in', 1], ['ap_done', 'out', 1], ['ap_idle', 'out', 1], ['ap_ready', 'out', 1], ['n', 'in', 8], ['remainder', 'out', 5], ['remainder_ap_vld', 'out', 1], ['ap_return', 'out', 4]]);
  }
  assert.match(ex.design.find(s => s.path === 'src/isqrt.c.vhd').text, /^-- Generated by Silinx from isqrt\.c/);
});

test('#1966 isqrt: C simulation: main() passes, no warnings', () => {
  const r = simulateC(C, { file: FILE });
  assert.equal(r.ok, true);
  assert.deepEqual(r.diagnostics, []);
  assert.equal(r.output, 'isqrt(200) = 14, remainder 4\nPASS\n');
});

for (const lang of ['vhdl', 'verilog']) {
  test(`#1966 isqrt: C/RTL co-simulation in ${lang}: every call as the C's, its latency following the root, no errors`, () => {
    const r = cosimulate(C, { file: FILE, lang });
    assert.equal(r.ok, true);
    assert.equal(r.pass, true);
    assert.equal(r.calls.length ?? r.calls, 257);
    assert.deepEqual(r.mismatches, []);
    assert.deepEqual(r.errors, []);
    assert.ok(r.latency.max > r.latency.min);
  });
}

test('#1966 isqrt: the test bench\'s check is the C\'s own: a wrong C fails main(), in C simulation', () => {
  const r = simulateC(C.replace('odd = odd + 2;', 'odd = odd + 1;'), { file: FILE });
  assert.match(r.output, /FAIL: \d+ wrong result\(s\)/);
});

test('#1966 isqrt: the display\'s test bench passes with the module generated in VHDL and in Verilog, no warning; with a wrong C it fails', async () => {
  for (const lang of ['vhdl', 'verilog']) {
    const hdl = viewHdl(FILE, C, { lang });
    const all = [{ path: `src/isqrt.c.${lang === 'vhdl' ? 'vhd' : 'v'}`, lang, role: 'design', text: hdl.text }, ...ex.sources.filter(s => !/isqrt\.c\./.test(s.path))];
    const lib = compile(all);
    const des = elaborate(lib, ex.project.simTop);
    assert.deepEqual([...lib.errors, ...des.diags].map(d => d.message), [], lang);
    const sim = new Simulator(des, { files: new Map(all.map(s => [s.path, s.text])) });
    for (const s of des.signals) s.wave = null;
    sim.run(5e9);
    const log = sim.log.map(e => e.text);
    assert.ok(log.includes('Simulation finished OK'), `${lang}: ${log.slice(-3).join('\n')}`);
    assert.deepEqual(sim.log.filter(e => e.kind === 'warning' || e.kind === 'error').map(e => e.text), [], lang);
  }
  const wrong = viewHdl(FILE, C.replace('root = root + 1;', 'root = root + 2;'), { lang: 'vhdl' });
  const r = await runTestbench('isqrt', { edit: { 'src/isqrt.c.vhd': wrong.text } });
  assert.equal(r.passed, false);
  assert.ok(r.log.some(l => /ERROR: n = \d+: the display shows/.test(l)));
});
